'use strict';
/**
 * Database access.
 *
 * Two separate SQLite files with different privileges:
 *   catalog.db  generated by the ingest script, opened READ ONLY by the web process.
 *               The public site can never write to it, so no request path can mutate
 *               the catalog even if a query were compromised.
 *   app.db      small writable store for contact and transfer request submissions.
 *
 * Every query below is a prepared statement with bound parameters. There is no
 * string concatenation of user input into SQL anywhere in this project.
 */
const fs = require('fs');
const path = require('path');
const Database = require('better-sqlite3');
const { config } = require('./config');

const catalog = new Database(config.dbPath, { readonly: config.dbReadonly, fileMustExist: true });
catalog.pragma('trusted_schema = OFF');

const appDbPath = path.join(config.root, 'data', 'app.db');
const appDb = new Database(appDbPath);
appDb.pragma('journal_mode = WAL');
appDb.pragma('trusted_schema = OFF');
appDb.exec(`
CREATE TABLE IF NOT EXISTS submissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL,
  created_at TEXT NOT NULL,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT,
  message TEXT,
  cart_json TEXT,
  consent_marketing INTEGER NOT NULL DEFAULT 0,
  consent_terms INTEGER NOT NULL DEFAULT 0,
  attested_eligible INTEGER NOT NULL DEFAULT 0,
  purge_after TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sub_created ON submissions(created_at);
`);
try { fs.chmodSync(appDbPath, 0o600); } catch { /* best effort on platforms without chmod */ }

/* ------------------------------------------------------------------ reads */

const PRODUCT_FIELDS = `id, slug, name, sku, price_cents, compare_cents, in_stock, product_class,
  model, caliber, caliber_slug, capacity, barrel_in, generation, optic_cut, summary, title_suffix,
  client_copy, has_client_copy, attr1_name, attr1_values, attr2_name, attr2_values,
  primary_image, image_count`;

const SORTS = {
  featured: 'p.in_stock DESC, p.image_count DESC, p.id ASC',
  'price-asc': 'p.price_cents ASC, p.id ASC',
  'price-desc': 'p.price_cents DESC, p.id ASC',
  'name-asc': 'p.name ASC, p.id ASC',
  // The WooCommerce id increments with creation order, so it is the only honest
  // proxy for "newest" available in the export. There is no date column in it.
  newest: 'p.id DESC'
};

const q = {
  categories: catalog.prepare('SELECT * FROM categories WHERE product_count > 0 ORDER BY grp, sort, name'),
  categoryBySlug: catalog.prepare('SELECT * FROM categories WHERE slug = ?'),
  productBySlug: catalog.prepare(`SELECT ${PRODUCT_FIELDS} FROM products WHERE slug = ?`),
  productById: catalog.prepare(`SELECT ${PRODUCT_FIELDS} FROM products WHERE id = ?`),
  imagesFor: catalog.prepare('SELECT filename, width, height, position FROM product_images WHERE product_id = ? ORDER BY position'),
  variantsFor: catalog.prepare('SELECT * FROM variants WHERE product_id = ? ORDER BY id'),
  categoriesFor: catalog.prepare(`SELECT c.* FROM categories c JOIN product_categories pc ON pc.category_id = c.id
                                  WHERE pc.product_id = ? ORDER BY c.grp, c.sort`),
  calibers: catalog.prepare(`SELECT caliber, caliber_slug, COUNT(*) n FROM products
                             WHERE caliber_slug IS NOT NULL GROUP BY caliber_slug HAVING n >= 3 ORDER BY n DESC`),
  allSlugs: catalog.prepare('SELECT slug FROM products ORDER BY id'),
  countAll: catalog.prepare('SELECT COUNT(*) c FROM products'),
  priceRange: catalog.prepare('SELECT MIN(price_cents) lo, MAX(price_cents) hi FROM products')
};

function listProducts({ categorySlug = null, caliberSlug = null, model = null, sort = 'featured', limit = 24, offset = 0 } = {}) {
  const order = SORTS[sort] || SORTS.featured;
  const where = [];
  const params = {};
  let join = '';
  if (categorySlug) {
    join = 'JOIN product_categories pc ON pc.product_id = p.id JOIN categories c ON c.id = pc.category_id';
    where.push('c.slug = @categorySlug');
    params.categorySlug = categorySlug;
  }
  if (caliberSlug) { where.push('p.caliber_slug = @caliberSlug'); params.caliberSlug = caliberSlug; }
  if (model) { where.push('p.model = @model'); params.model = model; }
  const clause = where.length ? 'WHERE ' + where.join(' AND ') : '';
  const rows = catalog.prepare(
    `SELECT ${PRODUCT_FIELDS.split(',').map((f) => 'p.' + f.trim()).join(', ')}
     FROM products p ${join} ${clause} ORDER BY ${order} LIMIT @limit OFFSET @offset`
  ).all({ ...params, limit, offset });
  const total = catalog.prepare(`SELECT COUNT(DISTINCT p.id) c FROM products p ${join} ${clause}`).get(params).c;
  return { rows, total };
}

function search(term, limit = 40) {
  const cleaned = String(term || '').replace(/[^\w\s.+-]/g, ' ').trim().slice(0, 60);
  if (!cleaned) return [];
  const match = cleaned.split(/\s+/).filter(Boolean).map((t) => `"${t}"*`).join(' ');
  try {
    return catalog.prepare(
      `SELECT ${PRODUCT_FIELDS.split(',').map((f) => 'p.' + f.trim()).join(', ')}
       FROM products_fts f JOIN products p ON p.id = f.rowid
       WHERE products_fts MATCH ? ORDER BY rank LIMIT ?`
    ).all(match, limit);
  } catch {
    return [];
  }
}

function relatedProducts(product, limit = 4) {
  if (product.model) {
    const r = catalog.prepare(
      `SELECT ${PRODUCT_FIELDS.split(',').map((f) => 'p.' + f.trim()).join(', ')}
       FROM products p WHERE p.model = ? AND p.id != ? ORDER BY p.image_count DESC, p.id LIMIT ?`
    ).all(product.model, product.id, limit);
    if (r.length) return r;
  }
  return catalog.prepare(
    `SELECT ${PRODUCT_FIELDS.split(',').map((f) => 'p.' + f.trim()).join(', ')}
     FROM products p WHERE p.id != ? ORDER BY p.image_count DESC LIMIT ?`
  ).all(product.id, limit);
}

/* ----------------------------------------------------------------- writes */

const insertSubmission = appDb.prepare(`INSERT INTO submissions
  (kind, created_at, name, email, phone, message, cart_json, consent_marketing, consent_terms, attested_eligible, purge_after)
  VALUES (@kind, @created_at, @name, @email, @phone, @message, @cart_json, @consent_marketing, @consent_terms, @attested_eligible, @purge_after)`);

function saveSubmission(rec) {
  const now = new Date();
  const retention = Number(config.business?.policy?.dataRetentionMonths || 24);
  const purge = new Date(now.getTime());
  purge.setMonth(purge.getMonth() + retention);
  return insertSubmission.run({
    kind: rec.kind,
    created_at: now.toISOString(),
    name: rec.name,
    email: rec.email,
    phone: rec.phone || null,
    message: rec.message || null,
    cart_json: rec.cartJson || null,
    consent_marketing: rec.consentMarketing ? 1 : 0,
    consent_terms: rec.consentTerms ? 1 : 0,
    attested_eligible: rec.attestedEligible ? 1 : 0,
    purge_after: purge.toISOString()
  }).lastInsertRowid;
}

// Retention: delete anything past its purge date. Called on boot and daily.
function purgeExpired() {
  return appDb.prepare('DELETE FROM submissions WHERE purge_after < ?').run(new Date().toISOString()).changes;
}

module.exports = {
  catalog, appDb, q, listProducts, search, relatedProducts, saveSubmission, purgeExpired
};
